19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
32	
33	const BLOCK_SIZE = 3;
34	const BLOCK_BASE_PREMIUM = 60;
35	
36	const groupedByType = (items: Item[]): Item[][] => {
37	  const groups = new Map<string, Item[]>();
38	
39	  for (const item of items) {
40	    const group = groups.get(item.type) ?? [];
41	    group.push(item);
42	    groups.set(item.type, group);
43	  }
44	
45	  return [...groups.values()];
46	};
47	
48	const basePremiumOfGroup = (group: Item[]): number =>
49	  group.length === BLOCK_SIZE
50	    ? BLOCK_BASE_PREMIUM
51	    : group.reduce((total, item) => total + basePremiumOf(item), 0);
52	
53	const totalBasePremiumOf = (items: Item[]): number =>
54	  groupedByType(items).reduce(
55	    (total, group) => total + basePremiumOfGroup(group),
56	    0,
57	  );
58	
59	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
60	
61	const quotePremium = (items: Item[]): number => {
62	  const basePremium = totalBasePremiumOf(items);
63	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
64	
65	  return roundedInMHPCOsFavour(
66	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
67	  );
68	};
69	
70	export const runScenario = (scenario: Scenario): ScenarioResult => ({
71	  results: scenario.steps.map((step) => ({
72	    premium: quotePremium(step.items),
73	  })),
74	});
