const alikeItemGroups = (items: Item[]): Item[][] => [
  ...Map.groupBy(items, (item) => item.type).values(),
];

const basePremiumOfGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : group.reduce((total, item) => total + basePremiumOf(item), 0);

const totalBasePremiumOf = (items: Item[]): number =>
  alikeItemGroups(items).reduce(
